def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator color is the repeated uniform-line color; background is the
    # most common color among non-separator cells.
    line_rows = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    line_cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    sep = grid[line_rows[0]][0] if line_rows else None

    row_cuts = [i for i in line_rows if all(v == sep for v in grid[i])]
    col_cuts = [j for j in line_cols if all(grid[i][j] == sep for i in range(h))]

    colors = {}
    for i, row in enumerate(grid):
        if i not in row_cuts:
            for j, v in enumerate(row):
                if j not in col_cuts:
                    colors[v] = colors.get(v, 0) + 1
    bg = max(colors, key=colors.get)
    marked = next(c for c in colors if c != bg)

    def intervals(n, cuts):
        result, start = [], 0
        for c in cuts + [n]:
            if c > start:
                result.append((start, c))
            start = c + 1
        return result

    rs = intervals(h, row_cuts)
    cs = intervals(w, col_cuts)
    return [
        [1 if sum(grid[i][j] == marked for i in range(r0, r1)
                  for j in range(c0, c1)) == 2 else bg
         for c0, c1 in cs]
        for r0, r1 in rs
    ]
